// the BIOS's code the program's handlers chain to: the timer's tick count; the sound driver's entries
// DOSBox-X's timer handler (F000:FEA5): sti; its callback (the tick count and, at midnight's 1800B0h, the day flag);
// push ds, ax, dx; int 1Ch (DOSBox-X's iret, or the program's handler if it took the vector); cli; the end of
// interrupt (out 20h: the highest in service); pop dx, ax, ds; iret. Its pushes stay below the stack pointer, as
// the program's later calls find them
static void bios_int8(void)
{
  u32 ticks = ((u32)mem_r16(0x46C) | ((u32)mem_r16(0x46E) << 16)) + 1;
  if (ticks >= 0x1800B0) { g_mem[0x470]++; ticks = 0; }
  mem_w16(0x46C, (u16)ticks);
  mem_w16(0x46E, (u16)(ticks >> 16));
  // the floppy motor's timeout (0040:0040): counted down, at 0 the motors' bits cleared; the EGA and VGA machines stop
  // at 0, the older ones go round
  const u8 motor = g_mem[0x440];
  if (motor || asm_machine >= 2) g_mem[0x440] = (u8)(motor - 1);
  if (motor == 1) g_mem[0x43F] &= 0xF0;
  const u16 sp = R.sp, cs = R.cs, ip = asm_ip;
  W16(SS, sp - 2, R.ds);
  W16(SS, sp - 4, R.ax);
  W16(SS, sp - 6, R.dx);
  R.if_ = true;
  R.sp = (u16)(sp - 6);
  R.cs = 0xF000;
  asm_ip = 0xFEAF;  // (after its int 1Ch)
  if (asm_vector_is_programs(0x1C)) asm_interrupt(0x1C);
  else
  {
    W16(SS, R.sp - 2, FLAGS16());
    W16(SS, R.sp - 4, R.cs);
    W16(SS, R.sp - 6, asm_ip);
  }
  R.cs = cs;
  asm_ip = ip;
  R.if_ = false;
  picIsr &= (u8)(picIsr - 1);
  R.sp = (u16)(sp + 6);
  SETFLAGS16_IRET(M16(SS, sp + 4));
}

// DOSBox-X's PS/2 mouse handler (IRQ 12, INT 74h): sti; push ds, es; pushad (the eight registers as 32 bits, their
// upper halves 0 in a 16-bit program); its callback (no routine of the program's to call: on to its return); cli;
// the ends of interrupt (out A0h, 20h); popad; pop es, ds; iret. Its pushes stay below the stack pointer
static void bios_int74(void)
{
  const u16 sp = R.sp;
  W16(SS, sp - 2, R.ds);
  W16(SS, sp - 4, R.es);
  const u16 regs[8] = { R.ax, R.cx, R.dx, R.bx, (u16)(sp - 4), R.bp, R.si, R.di };
  for (int k = 0; k < 8; k++)
  {
    W16(SS, sp - 8 - 4 * k, regs[k]);
    W16(SS, sp - 6 - 4 * k, 0);
  }
  R.sp = (u16)(sp + 6);
  SETFLAGS16_IRET(M16(SS, sp + 4));
}

static void outside(u16 seg, u16 off)
{
  for (int k = 0; k < 5; k++)
    if (*game_drivers[k].segp() && seg == *game_drivers[k].segp() && game_drivers[k].run(off)) return;
  {
    // a BIOS or DOS handler the vectors had when the program started (it saved them and chains, or calls one as an
    // interrupt): that vector's service, then its iret
    int n = dosboot_vector_of(seg, off);
    if (n == -2) { R.sp += 6; return; }  // (a default handler: an iret)
    if (n >= 0)
    {
      if (n == 8) { bios_int8(); return; }
      if (n == 0x74) { bios_int74(); return; }
      if (n == 9) picIsr &= (u8)~2;
      const u16 sp = R.sp;
      if (n == 0x21) asm_dos_entry(sp);  // (DOS reached by a far call: its entry's saves as an int's)
      asm_bios_service((u8)n);
      R.sp += 6;
      // a hardware interrupt's handler (IRQ 1-15) answers nothing: its iret takes the flags its caller pushed (who
      // may have cleared IF after: pushf; cli; call far); a service's keep its answer's
      if ((n >= 0x09 && n <= 0x0F) || (n >= 0x70 && n <= 0x77)) SETFLAGS16_IRET(M16(SS, sp + 4));
      return;
    }
  }
  // a replay: the program's own memory, code that is not recompiled (the replay cannot follow it); the BIOS's
  // elsewhere (its registers are the oracle's)
  if (replay_on && seg >= replay_progLo && seg < replay_progHi) replay_fail("a call to %04X:%04X, which is not recompiled", seg, off);
  if (seg != 0xF000 && replay_on) return;
  if (seg != 0xF000) fprintf(stderr, "game: outside call %04X:%04X (driver at %04X)\n", seg, off, pc15_seg);
  if (seg != 0xF000) asm_unknown_call(seg, off);
  if (off >= ASM_BIOS_VECTOR_OFF && off < ASM_BIOS_VECTOR_OFF + 256 && off != BIOS_TIMER_OFF)
  {
    if (off == ASM_BIOS_VECTOR_OFF + 9) picIsr &= (u8)~2;  // (the BIOS's keyboard handler ends the interrupt)
    asm_bios_service((u8)(off - ASM_BIOS_VECTOR_OFF));
    R.sp += 6;
    return;
  }
  if (off == BIOS_TIMER_OFF) { bios_int8(); return; }
  R.sp += 6;
}

// the CGA's wait state for one access of its memory, as DOSBox-X charges it: the full cost unless fewer than three
// times that many cycles are left in the processor's slice, which there ends at the next scan line (its drawing is
// an event a line), when the access is free
static u32 vram_cost(void)
{
  uint64_t t = asm_icount * (uint64_t)PIT_HZ / ((uint64_t)host->cycles * 1000);
  uint64_t start = frame_tick(frames), line = (frame_tick(frames + 1) - start) / 262;
  if (t < start || !line) return asm_vramCost;
  uint64_t left = line - (t - start) % line;  // ticks to the line's end
  uint64_t cycles = left * (uint64_t)host->cycles * 1000 / PIT_HZ;
  return cycles < 3 * asm_vramCost ? 0 : asm_vramCost;
}

// the requests the controller can hand to the processor now, each handler run to its return
static void pic_deliver(void)
{
  if (replay_on) return;  // (a replay: the oracle's interrupts, at its counts)
  for (int k = 0; R.if_ && k < 8; k++)
  {
    u8 bit = (u8)(1 << k);
    if (!(picIrr & bit) || (picMask & bit) || (picIsr & (u8)((bit << 1) - 1))) continue;
    picIrr &= (u8)~bit;
    picIsr |= bit;
    if (k == 1) { port60 = keyQueue[keyHead]; keyHead = (keyHead + 1) % 64; }
    asm_interrupt((u8)(8 + k));
    k = -1;  // (the handler may have let others through or raised new ones: from the top)
  }
}

uint64_t game_next_event(void)
{
  const uint64_t t = pit_next_irq(lastIrq);
  return t < nextFrame ? t : nextFrame;
}
uint32_t game_cycles(void) { return host->cycles; }

// time passes: the timer's interrupts, the keys, the frames
void asm_back_slow(void)
{
  if (replay_on) { asm_backBudget = 1 << 30; return; }  // (a replay: the oracle's interrupts and frame ends)
  asm_backBudget = 4;
  // the instructions so far at the machine's speed: PIT ticks = instructions * 1193182 / (cycles * 1000)
  now = asm_icount * (uint64_t)PIT_HZ / ((uint64_t)host->cycles * 1000);
  for (;;)
  {
    uint64_t t = pit_next_irq(lastIrq);
    if (t > now) break;
    lastIrq = t;
    picIrr |= 1;
  }
  if (sb_irq_due(now)) picIrr |= (u8)(1 << sbIrq);
  if (keyHead != keyTail) picIrr |= 2;
  pic_deliver();
  while (now >= nextFrame)
  {
    if (!host->frame(host->ctx, frames++)) game_exit(-1);
    nextFrame = frame_tick(frames + 1);
  }
}



int game_setup(const GameHost *h)
{
  host = h;
  startError[0] = 0;
  pthread_mutex_lock(&disksLock);
  if (!diskFiles && disks_present(host->gameDir) && (diskCount = disks_load(host->gameDir, &diskFiles, startError, sizeof startError)) < 0)
  {
    diskCount = 0;
    diskFiles = NULL;
    pthread_mutex_unlock(&disksLock);
    fprintf(stderr, "game: %s\n", startError);
    return -1;
  }
  pthread_mutex_unlock(&disksLock);
  memset(g_mem, 0, sizeof g_mem);
  now = lastIrq = frames = 0;
  asm_icount = 0;
  picIrr = picIsr = 0;
  R.if_ = true;
  asm_sti_hook = pic_deliver;
  // the machine idle before the program starts (the host's idleTicks: DOS loading it, in the oracle's terms): the
  // frames of that time shown, the clocks run on
  if (host->idleTicks)
  {
    asm_icount = host->idleTicks * (uint64_t)host->cycles * 1000 / PIT_HZ;
    now = lastIrq = asm_icount * (uint64_t)PIT_HZ / ((uint64_t)host->cycles * 1000);
    while (now >= frame_tick(frames + 1)) { if (!host->frame(host->ctx, frames)) return -1; frames++; }
  }
  nextFrame = frame_tick(frames + 1);
  keyHead = keyTail = 0;
  pit_reset();
  sb_reset();
  opl_reset();
  tandy_reset();
  mpu_reset();
  // the BIOS's vectors and data area, the environment and the PSP as DOSBox-X's leave them (dosboot.c); the tick
  // count the ticks since midnight at the start (18.2065 a second)
  programIndex = 0;
  for (int k = 0; k < 4; k++) if (host->program && !strcasecmp(host->program, programs[k].file)) programIndex = k;
  const GameProgram *program = &programs[programIndex];
  asm_machine = programIndex;
  {
    int64_t secs = host->startTime % 86400;
    u32 ticks = (u32)((double)secs * 18.2065 + (double)(host->startTicks + (int64_t)now) * 18.2065 / PIT_HZ);
    char programPath[64];
    snprintf(programPath, sizeof programPath, "C:\\BOXU\\%s", program->file);
    dosboot_setup(GAME_ENV_SEG, GAME_PSP_SEG, dosboot_mem_end(), programPath, host->cmdline ? host->cmdline : "", ticks);
  }
  // the Tandy's video memory: the page register as its BIOS left it (the others: none)
  asm_tandyBase = 0;
  if (asm_machine == 3) asm_tandy_set_page(g_mem[0x48A]);
  // DOS's memory: the program gets everything from its PSP on (its start-up gives back what it does not need)
  dos_owner = GAME_PSP_SEG;
  {
    char name[9] = { 0 };
    for (int k = 0; k < 8 && program->file[k] && program->file[k] != '.'; k++) name[k] = program->file[k];
    dos_set_program_name(name);
  }
  dos_set_arena((u16)(GAME_PSP_SEG - 1), dosboot_mem_end());
  u16 seg = dos_alloc(dos_largest_free());
  if (seg != GAME_PSP_SEG) { fprintf(stderr, "game: the program's block is at %04X, not %04X\n", seg, GAME_PSP_SEG); return -1; }
  // the program: from the disks, or the folder's (its name in capitals, then in small letters)
  ExeInfo e;
  bool loaded = false;
  if (diskFiles)
  {
    const DosFile *exe = NULL;
    for (int k = 0; k < diskCount && !exe; k++)
      if (!strcasecmp(diskFiles[k].name, program->file)) exe = &diskFiles[k];
    loaded = exe && exe_load_mem(exe->data, exe->size, GAME_LOAD_SEG, &e);
    if (!loaded)
      snprintf(startError, sizeof startError, "%s: %s %s", host->gameDir, program->file,
               exe ? "on the disks is not a program this loads" : "is not on the disks");
  }
  else
  {
    char path[1024], lower[32];
    snprintf(path, sizeof path, "%s/%s", host->gameDir ? host->gameDir : ".", program->file);
    loaded = exe_load(path, GAME_LOAD_SEG, &e);
    if (!loaded)
    {
      for (int k = 0; k < 31 && program->file[k]; k++) lower[k] = (char)tolower((unsigned char)program->file[k]), lower[k + 1] = 0;
      snprintf(path, sizeof path, "%s/%s", host->gameDir ? host->gameDir : ".", lower);
      loaded = exe_load(path, GAME_LOAD_SEG, &e);
    }
    if (!loaded) snprintf(startError, sizeof startError, "cannot load %s", path);
  }
  if (!loaded)
  {
    fprintf(stderr, "game: %s\n", startError);
    return -1;
  }
  g_dsSeg = program->ds;
  asm_set_program_segments(GAME_LOAD_SEG, (u16)(GAME_LOAD_SEG + e.imageParagraphs + 0x1000));
  dosHost.gameDir = host->gameDir;
  dosHost.writeDir = host->writeDir;
  dosHost.files = diskFiles;
  dosHost.fileCount = diskCount;
  dos_attach(&dosHost);
  asm_port_hook = port_in;
  asm_port_out_hook = port_out;
  // the ISA bus's time for a port access, in instructions at the machine's speed (asm2c.h)
  asm_ioCostIn = (u32)((uint64_t)host->cycles * 1020 / 1000000);
  asm_ioCostOut = (u32)((uint64_t)host->cycles * 1020 * 3 / 4000000);
  asm_ioCostIn16 = (u32)((uint64_t)host->cycles * 660 / 1000000);
  asm_ioCostOut16 = (u32)((uint64_t)host->cycles * 660 * 3 / 4000000);
  // the CGA's wait states (DOSBox-X's CGA machine: 2.8 us a byte of its memory, cycles / (1024 / 2.8) as an integer)
  asm_vramCost = programIndex == 2 ? host->cycles / 365 : 0;
  asm_vram_cost_hook = vram_cost;
  asm_outside_hook = outside;
  asm_dispatch_hook = program->dispatch;
  if (!asm_fn_hook) asm_fn_hook = cheats_fn;  // (a host tracing the entries calls cheats_fn itself)
  cheats_reset();
  dos_read_hook = read_hook;
  for (int k = 0; k < 5; k++) *game_drivers[k].segp() = 0;
  // the registers as DOS starts the program
  // the registers as DOS (DOSBox-X's EXEC) starts the program: AX = BX = 0 (the FCB drives' validity), CX = 00FF,
  // DX = DS = ES = the PSP, SI = the entry's IP, DI = the stack's SP, BP = 091C, interrupts on, IOPL and NT set
  R = (Regs){ 0 };
  R.ds = R.es = GAME_PSP_SEG;
  R.dx = GAME_PSP_SEG;
  R.cx = 0x00FF;
  R.si = e.ip;
  R.di = e.sp;
  R.bp = 0x091C;
  R.xf = 0x7000;
  R.if_ = true;
  R.ss = e.ss;
  R.sp = g_sp = e.sp;
  R.cs = e.cs;
  // (DOSBox-X's EXEC starts it with a far return: the entry's address stays below the stack pointer)
  W16(SS, R.sp - 4, e.ip);
  W16(SS, R.sp - 2, e.cs);
  asm_backBudget = 1;
  exitCode = 0;
  return 0;
}

int game_run(const GameHost *h)
{
  if (game_setup(h) < 0) return -1;
  const GameProgram *program = &programs[programIndex];
  if (!setjmp(exitJump)) program->crt0();
  dos_close_all();
  return exitCode;
}

// quickerOpen4DBoxing: the program entered again to resume where it stopped (asm_resuming set: each
// function on the way goes to the call site the shadow stack names); its exit as game_run's
int game_resume(void)
{
  const GameProgram *program = &programs[programIndex];
  exitCode = 0;
  if (!setjmp(exitJump)) program->crt0();
  dos_close_all();
  return exitCode;
}
// the frame count (the frames shown so far) and the clock, as the machine's own
uint64_t game_frames(void) { return frames; }

// quickerOpen4DBoxing: this file's part of a machine's state (tools/generate.py)
#include <stddef.h>
void o4db_state_game(void (*v)(void *data, size_t size, void *c), void *c)
{
  v((void *)(&exitCode), sizeof(exitCode), c);
  v((void *)(&now), sizeof(now), c);
  v((void *)(&lastIrq), sizeof(lastIrq), c);
  v((void *)(&frames), sizeof(frames), c);
  v((void *)(&nextFrame), sizeof(nextFrame), c);
  v((void *)(keyQueue), sizeof(keyQueue), c);
  v((void *)(&keyHead), sizeof(keyHead), c);
  v((void *)(&keyTail), sizeof(keyTail), c);
  v((void *)(&port60), sizeof(port60), c);
  v((void *)(&picMask), sizeof(picMask), c);
  v((void *)(&picIrr), sizeof(picIrr), c);
  v((void *)(&picIsr), sizeof(picIsr), c);
  v((void *)(&sbIrq), sizeof(sbIrq), c);
  v((void *)(&joyStart), sizeof(joyStart), c);
}
